<?php
declare(strict_types=1);require __DIR__.'/../backend/src/CardProviders.php';
function providerCheck(bool $pass,string $name):void{if(!$pass)throw new RuntimeException($name);echo "PASS: $name\n";}
$config=['enabled'=>true,'gemini'=>['freeTierConfirmed'=>true,'key'=>'synthetic-fixture','model'=>'fixture-model'],'cloudflare'=>['freeTierConfirmed'=>true,'key'=>'synthetic-fixture','accountId'=>str_repeat('a',32)]];
$draft=['title'=>'Synthetic card','category'=>'history','rarity'=>'common','story'=>'This is synthetic test content. It makes no religious claim. A third sentence tests the schema.','imagePrompt'=>'An empty architectural courtyard','references'=>[['title'=>'Synthetic fixture','url'=>'https://example.invalid/fixture']],'verification'=>'verified'];
$draft+=['titleUrdu'=>'آزمائشی کہانی','summary'=>$draft['story'],'summaryUrdu'=>'یہ صرف جانچ کے لیے ایک مختصر تعارف ہے۔','english'=>$draft['story'],'urdu'=>'یہ آزمائشی کہانی ہے۔ اس میں کوئی تاریخی یا مذہبی دعویٰ نہیں ہے۔ تیسرا جملہ قاری اور زبان کی جانچ کے لیے ہے۔'];
$called=0;$provider=new CardProviders($config,static function($url,$headers,$body,$max)use($draft,&$called){$called++;providerCheck(!str_contains($url,'key='),'provider key stays out of URLs');providerCheck($body['generationConfig']['responseMimeType']==='application/json','Gemini requests structured JSON');return ['candidates'=>[['finishReason'=>'STOP','content'=>['parts'=>[['text'=>json_encode($draft)]]]]]];});
providerCheck($provider->draft(['title'=>'Synthetic topic','category'=>'history','rarity'=>'common'])['verification']==='draft','provider cannot approve its own generated content');
$disabled=new CardProviders(array_merge($config,['enabled'=>false]),static function(){throw new RuntimeException('Disabled provider called');});try{$disabled->draft(['title'=>'x','category'=>'history','rarity'=>'common']);throw new LogicException('Disabled generation accepted');}catch(RuntimeException $e){providerCheck(str_contains($e->getMessage(),'disabled'),'disabled providers make no network call');}
$bytes=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=');
$image=new CardProviders($config,static function($url,$headers,$body,$max)use($bytes){providerCheck(str_contains($body['prompt'],'No humans'),'image request stays symbolic');providerCheck($body['steps']<=4,'bounded image steps');return ['success'=>true,'result'=>['image'=>base64_encode($bytes)]];});
providerCheck($image->image('Empty courtyard')['mime']==='image/png','valid image bytes validated independently of response label');
$bad=new CardProviders($config,static fn()=>['success'=>true,'result'=>['image'=>base64_encode('<script>bad</script>')]]);try{$bad->image('Empty landscape');throw new LogicException('Non-image accepted');}catch(RuntimeException){providerCheck(true,'non-image response refused');}
